// scene = grupo com transform-style: preserve-3d; items = camadas (fundo para frente)
tl.fromTo(scene, { rotationX: 0, rotationZ: 0, transformPerspective: 1600 }, { rotationX: 55, rotationZ: -25, duration: 0.8, ease: "power3.inOut" }, t);
tl.fromTo(items, { z: 0 }, { z: (i) => i * 120, duration: 0.8, ease: "power3.inOut" }, t + 0.2);

// el = página; items[0] = verso dobrado (mesmo tamanho, gradiente claro + sombra), por cima
const flap = items[0], d = 35;
tl.fromTo(el, { clipPath: "polygon(0% 0%, 100% 0%, 100% 100%, 100% 100%, 0% 100%)" }, { clipPath: `polygon(0% 0%, 100% 0%, 100% ${100 - d}%, ${100 - d}% 100%, 0% 100%)`, duration: 0.9, ease: "power2.inOut" }, t);
tl.fromTo(flap, { clipPath: "polygon(100% 100%, 100% 100%, 100% 100%)" }, { clipPath: `polygon(100% ${100 - d}%, ${100 - d}% 100%, ${100 - d}% ${100 - d}%)`, duration: 0.9, ease: "power2.inOut" }, t);

const rng = (s) => () => ((s = (s * 16807) % 2147483647) / 2147483647); // pseudoaleatório com seed fixa

// items = letras ou fragmentos já no lugar final; pai com perspective: 1200px
const r = rng(21), p = items.map(() => ({ x: (r() - 0.5) * 1200, y: (r() - 0.5) * 1600, z: -400 - r() * 1200, rx: (r() - 0.5) * 360, ry: (r() - 0.5) * 360 }));
tl.fromTo(items, { x: (i) => p[i].x, y: (i) => p[i].y, z: (i) => p[i].z, rotationX: (i) => p[i].rx, rotationY: (i) => p[i].ry, opacity: 0 }, { x: 0, y: 0, z: 0, rotationX: 0, rotationY: 0, opacity: 1, duration: 1.1, ease: "expo.out", stagger: 0.03 }, t);

// el = cubo (preserve-3d) com 4 faces em rotateX(i*90deg) translateZ(100px)
tl.set(el, { rotationX: 0, transformPerspective: 1200 }, t);
[1, 2, 3].forEach((k) => tl.fromTo(el, { rotationX: -(k - 1) * 90 }, { rotationX: -k * 90, duration: 0.5, ease: "back.inOut(1.4)", immediateRender: false }, t + (k - 1) * 1.0));
